mapper.select:
SELECT SEQ, PURPOSE, PHONE, CODE, ATTEMPTS, CREATED_AT, VERIFIED_AT
FROM signup_sms_verification
WHERE PURPOSE = #{purpose} AND PHONE = #{phone}

mapper.update:
UPDATE signup_sms_verification
SET ATTEMPTS = ATTEMPTS + 1
WHERE PURPOSE = #{purpose} AND PHONE = #{phone}

UPDATE signup_sms_verification
SET VERIFIED_AT = #{verifiedAt},
    CODE = NULL
WHERE PURPOSE = #{purpose}
  AND PHONE = #{phone}
  AND CODE = #{code}
  AND VERIFIED_AT IS NULL
